// Generate a random C-string payload; FUZZ_PARAM_STR() returns a std::string
// which provides a valid, non-null, null-terminated buffer via c_str().
std::string s = FUZZ_PARAM_STR();
const char *cstr = s.c_str();

// Property: determinism with the same input and seed (default seed).
unsigned int h1 = constexprHash(cstr);
unsigned int h2 = constexprHash(cstr);
FUZZ_ASSERT(h1 == h2, "Hash must be deterministic for identical input with default seed");

// Property: explicit default seed equals implicit default seed.
unsigned int h_default_explicit = constexprHash(cstr, fnv1a32val);
FUZZ_ASSERT(h1 == h_default_explicit, "Explicit default seed must match implicit default");

// Exercise custom seed path using a fuzzed seed.
unsigned int custom_seed = *FUZZ_PARAM(unsigned int);
unsigned int h_custom = constexprHash(cstr, custom_seed);
(void)h_custom; // Value is not asserted (custom_seed may equal default or differ), but path is exercised.

// Validation summary:
// - Ensures non-null, null-terminated input via std::string::c_str().
// - Asserts determinism and default-seed equivalence; exercises custom-seed code path.
